00180 void CodingStructure::setDecomp(const CompArea &_area, const bool _isCoded /*= true*/)
00181 {
00182   const UnitScale& scale = unitScale[_area.compID];
00183 
00184   AreaBuf<bool> isCodedBlk( m_isDecomp[toChannelType( _area.compID )] + rsAddr( _area, area.blocks[_area.compID].pos(), area.blocks[_area.compID].width, scale ),
00185                             area.blocks[_area.compID].width >> scale.posx,
00186                             _area.width                     >> scale.posx,
00187                             _area.height                    >> scale.posy);
00188   isCodedBlk.fill( _isCoded );
00189 }
