00222 void CodingStructure::clearCuPuTuIdxMap( const UnitArea &_area, uint32_t numCu, uint32_t numPu, uint32_t numTu, uint32_t* pOffset )
00223 {
00224   UnitArea clippedArea = clipArea( _area, *picture );
00225   uint32_t numCh = vtm::getNumberValidChannels( _area.chromaFormat );
00226   for( uint32_t i = 0; i < numCh; i++ )
00227   {
00228     const CompArea &_selfBlk = area.blocks[i];
00229     const CompArea     &_blk = clippedArea.blocks[i];
00230 
00231     const UnitScale& scale = unitScale[_blk.compID];
00232     const Area scaledSelf = scale.scale( _selfBlk );
00233     const Area scaledBlk = scale.scale( _blk );
00234     const size_t offset = rsAddr( scaledBlk.pos(), scaledSelf.pos(), scaledSelf.width );
00235     unsigned *idxPtrCU = m_cuIdx[i] + offset;
00236     AreaBuf<uint32_t>( idxPtrCU, scaledSelf.width, scaledBlk.size() ).fill( 0 );
00237 
00238     unsigned *idxPtrPU = m_puIdx[i] + offset;
00239     AreaBuf<uint32_t>( idxPtrPU, scaledSelf.width, scaledBlk.size() ).fill( 0 );
00240 
00241     unsigned *idxPtrTU = m_tuIdx[i] + offset;
00242     AreaBuf<uint32_t>( idxPtrTU, scaledSelf.width, scaledBlk.size() ).fill( 0 );
00243   }
00244 
00245   //pop cu/pu/tus
00246   for( int i = m_numTUs; i > numTu; i-- )
00247   {
00248     m_tuCache.cache( tus.back() );
00249     tus.pop_back();
00250     m_numTUs--;
00251   }
00252   for( int i = m_numPUs; i > numPu; i-- )
00253   {
00254     m_puCache.cache( pus.back() );
00255     pus.pop_back();
00256     m_numPUs--;
00257   }
00258   for( int i = m_numCUs; i > numCu; i-- )
00259   {
00260     m_cuCache.cache( cus.back() );
00261     cus.pop_back();
00262     m_numCUs--;
00263   }
00264   for( int i = 0; i < 3; i++ )
00265   {
00266     m_offsets[i] = pOffset[i];
00267   }
00268 }
