00419 TransformUnit* CodingStructure::getTU( const Position &pos, const ChannelType effChType, const int subTuIdx )
00420 {
00421   const CompArea &_blk = area.blocks[effChType];
00422 
00423   if( !_blk.contains( pos ) )
00424   {
00425     if (parent)
00426     {
00427       return parent->getTU(pos, effChType);
00428     }
00429     else
00430     {
00431       return nullptr;
00432     }
00433   }
00434   else
00435   {
00436     const unsigned idx = m_tuIdx[effChType][rsAddr( pos, _blk.pos(), _blk.width, unitScale[effChType] )];
00437 
00438     if( idx != 0 )
00439     {
00440       unsigned extraIdx = 0;
00441       if( isLuma( effChType ) )
00442       {
00443         const TransformUnit& tu = *tus[idx - 1];
00444 
00445         if( tu.cu->ispMode ) // Intra SubPartitions mode
00446         {
00447           //we obtain the offset to index the corresponding sub-partition
00448           if( subTuIdx != -1 )
00449           {
00450             extraIdx = subTuIdx;
00451           }
00452           else
00453           {
00454             while( !tus[idx - 1 + extraIdx]->blocks[getFirstComponentOfChannel( effChType )].contains( pos ) )
00455             {
00456               extraIdx++;
00457               CHECK( tus[idx - 1 + extraIdx]->cu->treeType == TREE_C, "tu searched by position points to a chroma tree CU" );
00458               CHECK( extraIdx > 3, "extraIdx > 3" );
00459             }
00460           }
00461         }
00462       }
00463       return tus[idx - 1 + extraIdx];
00464     }
00465     else if (m_isTuEnc)
00466     {
00467       return parent->getTU(pos, effChType);
00468     }
00469     else
00470     {
00471       return nullptr;
00472     }
00473   }
00474 }
