00531 CodingUnit& CodingStructure::addCU( const UnitArea &unit, const ChannelType chType )
00532 {
00533   CodingUnit *cu = m_cuCache.get();
00534 
00535   cu->UnitArea::operator=( unit );
00536   cu->initData();
00537   cu->cs        = this;
00538   cu->slice     = nullptr;
00539   cu->next      = nullptr;
00540   cu->firstPU   = nullptr;
00541   cu->lastPU    = nullptr;
00542   cu->firstTU   = nullptr;
00543   cu->lastTU    = nullptr;
00544   cu->chType    = chType;
00545   cu->treeType = treeType;
00546   cu->modeType = modeType;
00547 
00548   CodingUnit *prevCU = m_numCUs > 0 ? cus.back() : nullptr;
00549 
00550   if( prevCU )
00551   {
00552     prevCU->next = cu;
00553 #if ENABLE_SPLIT_PARALLELISM
00554 
00555     CHECK( prevCU->cacheId != cu->cacheId, "Inconsintent cacheId between previous and current CU" );
00556 #endif
00557   }
00558 
00559   cus.push_back( cu );
00560 
00561   uint32_t idx = ++m_numCUs;
00562   cu->idx  = idx;
00563 
00564   uint32_t numCh = vtm::getNumberValidChannels( area.chromaFormat );
00565 
00566   for( uint32_t i = 0; i < numCh; i++ )
00567   {
00568     if( !cu->blocks[i].valid() )
00569     {
00570       continue;
00571     }
00572 
00573     const CompArea &_selfBlk = area.blocks[i];
00574     const CompArea     &_blk = cu-> blocks[i];
00575 
00576     const UnitScale& scale = unitScale[_blk.compID];
00577     const Area scaledSelf  = scale.scale( _selfBlk );
00578     const Area scaledBlk   = scale.scale(     _blk );
00579     unsigned *idxPtr       = m_cuIdx[i] + rsAddr( scaledBlk.pos(), scaledSelf.pos(), scaledSelf.width );
00580     CHECK( *idxPtr, "Overwriting a pre-existing value, should be '0'!" );
00581     AreaBuf<uint32_t>( idxPtr, scaledSelf.width, scaledBlk.size() ).fill( idx );
00582   }
00583 
00584   return *cu;
00585 }
00586 
00587 PredictionUnit& CodingStructure::addPU( const UnitArea &unit, const ChannelType chType )
00588 {
00589   PredictionUnit *pu = m_puCache.get();
00590 
00591   pu->UnitArea::operator=( unit );
00592   pu->initData();
00593   pu->next   = nullptr;
00594   pu->cs     = this;
00595   pu->cu     = m_isTuEnc ? cus[0] : getCU( unit.blocks[chType].pos(), chType );
00596   pu->chType = chType;
00597 #if ENABLE_SPLIT_PARALLELISM
00598 
00599   CHECK( pu->cacheId != pu->cu->cacheId, "Inconsintent cacheId between the PU and assigned CU" );
00600   CHECK( pu->cu->firstPU != nullptr, "Without an RQT the firstPU should be null" );
00601 #endif
00602 
00603   PredictionUnit *prevPU = m_numPUs > 0 ? pus.back() : nullptr;
00604 
00605   if( prevPU && prevPU->cu == pu->cu )
00606   {
00607     prevPU->next = pu;
00608 #if ENABLE_SPLIT_PARALLELISM
00609 
00610     CHECK( prevPU->cacheId != pu->cacheId, "Inconsintent cacheId between previous and current PU" );
00611 #endif
00612   }
00613 
00614   pus.push_back( pu );
00615 
00616   if( pu->cu->firstPU == nullptr )
00617   {
00618     pu->cu->firstPU = pu;
00619   }
00620   pu->cu->lastPU = pu;
00621 
00622   uint32_t idx = ++m_numPUs;
00623   pu->idx  = idx;
00624 
00625   uint32_t numCh = vtm::getNumberValidChannels( area.chromaFormat );
00626   for( uint32_t i = 0; i < numCh; i++ )
00627   {
00628     if( !pu->blocks[i].valid() )
00629     {
00630       continue;
00631     }
00632 
00633     const CompArea &_selfBlk = area.blocks[i];
00634     const CompArea     &_blk = pu-> blocks[i];
00635 
00636     const UnitScale& scale = unitScale[_blk.compID];
00637     const Area scaledSelf  = scale.scale( _selfBlk );
00638     const Area scaledBlk   = scale.scale(     _blk );
00639     unsigned *idxPtr       = m_puIdx[i] + rsAddr( scaledBlk.pos(), scaledSelf.pos(), scaledSelf.width );
00640     CHECK( *idxPtr, "Overwriting a pre-existing value, should be '0'!" );
00641     AreaBuf<uint32_t>( idxPtr, scaledSelf.width, scaledBlk.size() ).fill( idx );
00642   }
00643 
00644   return *pu;
00645 }
