00647 TransformUnit& CodingStructure::addTU( const UnitArea &unit, const ChannelType chType )
00648 {
00649   TransformUnit *tu = m_tuCache.get();
00650 
00651   tu->UnitArea::operator=( unit );
00652   tu->initData();
00653   tu->next   = nullptr;
00654   tu->prev   = nullptr;
00655   tu->cs     = this;
00656   tu->cu     = m_isTuEnc ? cus[0] : getCU( unit.blocks[chType].pos(), chType );
00657   tu->chType = chType;
00658 #if ENABLE_SPLIT_PARALLELISM
00659 
00660   if( tu->cu )
00661   {
00662     CHECK(tu->cacheId != tu->cu->cacheId, "Inconsintent cacheId between the TU and assigned CU");
00663   }
00664 #endif
00665 
00666 
00667   TransformUnit *prevTU = m_numTUs > 0 ? tus.back() : nullptr;
00668 
00669   if( prevTU && prevTU->cu == tu->cu )
00670   {
00671     prevTU->next = tu;
00672     tu->prev     = prevTU;
00673 #if ENABLE_SPLIT_PARALLELISM
00674 
00675     CHECK( prevTU->cacheId != tu->cacheId, "Inconsintent cacheId between previous and current TU" );
00676 #endif
00677   }
00678 
00679   tus.push_back( tu );
00680 
00681   if( tu->cu )
00682   {
00683     if( tu->cu->firstTU == nullptr )
00684     {
00685       tu->cu->firstTU = tu;
00686     }
00687     tu->cu->lastTU = tu;
00688   }
00689 
00690   uint32_t idx = ++m_numTUs;
00691   tu->idx  = idx;
00692 
00693   TCoeff *coeffs[5] = { nullptr, nullptr, nullptr, nullptr, nullptr };
00694   Pel    *pcmbuf[5] = { nullptr, nullptr, nullptr, nullptr, nullptr };
00695   bool   *runType[5]   = { nullptr, nullptr, nullptr, nullptr, nullptr };
00696 
00697   uint32_t numCh = vtm::getNumberValidComponents( area.chromaFormat );
00698 
00699   for (uint32_t i = 0; i < numCh; i++)
00700   {
00701     if (!tu->blocks[i].valid())
00702     {
00703       continue;
00704     }
00705 
00706     if (i < vtm::getNumberValidChannels(area.chromaFormat))
00707     {
00708       const CompArea &_selfBlk = area.blocks[i];
00709       const CompArea     &_blk = tu->blocks[i];
00710 
00711       bool isIspTu = tu->cu != nullptr && tu->cu->ispMode && isLuma(_blk.compID);
00712 
00713       bool isFirstIspTu = false;
00714       if (isIspTu)
00715       {
00716         isFirstIspTu = CU::isISPFirst(*tu->cu, _blk, getFirstComponentOfChannel(ChannelType(i)));
00717       }
00718       if (!isIspTu || isFirstIspTu)
00719       {
00720         const UnitScale& scale = unitScale[_blk.compID];
00721 
00722         const Area scaledSelf = scale.scale(_selfBlk);
00723         const Area scaledBlk = isIspTu ? scale.scale(tu->cu->blocks[i]) : scale.scale(_blk);
00724         unsigned *idxPtr = m_tuIdx[i] + rsAddr(scaledBlk.pos(), scaledSelf.pos(), scaledSelf.width);
00725         CHECK(*idxPtr, "Overwriting a pre-existing value, should be '0'!");
00726         AreaBuf<uint32_t>(idxPtr, scaledSelf.width, scaledBlk.size()).fill(idx);
00727       }
00728     }
00729 
00730     coeffs[i] = m_coeffs[i] + m_offsets[i];
00731     pcmbuf[i] = m_pcmbuf[i] + m_offsets[i];
00732 
00733     if (i < MAX_NUM_CHANNEL_TYPE)
00734     {
00735       if (m_runType[i] != nullptr)
00736       {
00737         runType[i] = m_runType[i] + m_offsets[i];
00738       }
00739     }
00740 
00741     unsigned areaSize = tu->blocks[i].area();
00742     m_offsets[i] += areaSize;
00743   }
00744   tu->init(coeffs, pcmbuf, runType);
00745 
00746   return *tu;
00747 }
00748 
00749 void CodingStructure::addEmptyTUs( Partitioner &partitioner )
00750 {
00751   const UnitArea& area    = partitioner.currArea();
00752   bool            split   = partitioner.canSplit(TU_MAX_TR_SPLIT, *this);
00753   const unsigned  trDepth = partitioner.currTrDepth;
00754 
00755   if( split )
00756   {
00757     partitioner.splitCurrArea( TU_MAX_TR_SPLIT, *this );
00758     do
00759     {
00760       addEmptyTUs( partitioner );
00761     } while( partitioner.nextPart( *this ) );
00762 
00763     partitioner.exitCurrSplit();
00764   }
00765   else
00766   {
00767     TransformUnit &tu = this->addTU( CS::getArea( *this, area, partitioner.chType ), partitioner.chType );
00768     unsigned numBlocks = vtm::getNumberValidTBlocks( *this->pcv );
00769     for( unsigned compID = COMPONENT_Y; compID < numBlocks; compID++ )
00770     {
00771       if( tu.blocks[compID].valid() )
00772       {
00773         tu.getCoeffs( ComponentID( compID ) ).fill( 0 );
00774         tu.getPcmbuf( ComponentID( compID ) ).fill( 0 );
00775       }
00776     }
00777     tu.depth = trDepth;
00778   }
00779 }
