00781 CUTraverser CodingStructure::traverseCUs( const UnitArea& unit, const ChannelType effChType )
00782 {
00783   CodingUnit* firstCU = getCU( isLuma( effChType ) ? unit.lumaPos() : unit.chromaPos(), effChType );
00784   CodingUnit* lastCU = firstCU;
00785   if( !CS::isDualITree( *this ) ) //for a more generalized separate tree
00786   {
00787     bool bContinue = true;
00788     CodingUnit* currCU = firstCU;
00789     while( bContinue )
00790     {
00791       if( currCU == nullptr )
00792       {
00793         bContinue = false;
00794         lastCU = currCU;
00795       }
00796       else if( currCU->chType != effChType )
00797       {
00798         lastCU = currCU;
00799         currCU = currCU->next;
00800       }
00801       else
00802       {
00803         if( unit.contains( *currCU ) )
00804         {
00805           lastCU = currCU;
00806           currCU = currCU->next;
00807         }
00808         else
00809         {
00810           bContinue = false;
00811           lastCU = currCU;
00812         }
00813       }
00814     }
00815   }
00816   else
00817   {
00818     do
00819     {
00820     } while (lastCU && (lastCU = lastCU->next) && unit.contains(*lastCU));
00821   }
00822 
00823   return CUTraverser( firstCU, lastCU );
00824 }
