00918 void CodingStructure::createInternals(const UnitArea& _unit, const bool isTopLayer, const bool isPLTused)
00919 {
00920   area = _unit;
00921 
00922   memcpy( unitScale, UnitScaleArray[area.chromaFormat], sizeof( unitScale ) );
00923 
00924   picture = nullptr;
00925   parent  = nullptr;
00926 
00927   unsigned numCh = vtm::getNumberValidChannels(area.chromaFormat);
00928 
00929   for (unsigned i = 0; i < numCh; i++)
00930   {
00931     unsigned _area = unitScale[i].scale( area.blocks[i].size() ).area();
00932 
00933     m_cuIdx[i]    = _area > 0 ? new unsigned[_area] : nullptr;
00934     m_puIdx[i]    = _area > 0 ? new unsigned[_area] : nullptr;
00935     m_tuIdx[i]    = _area > 0 ? new unsigned[_area] : nullptr;
00936     m_isDecomp[i] = _area > 0 ? new bool    [_area] : nullptr;
00937   }
00938 
00939   numCh = getNumberValidComponents(area.chromaFormat);
00940 
00941   for (unsigned i = 0; i < numCh; i++)
00942   {
00943     m_offsets[i] = 0;
00944   }
00945 
00946   if( !isTopLayer ) createCoeffs(isPLTused);
00947 
00948   unsigned _lumaAreaScaled = g_miScaling.scale( area.lumaSize() ).area();
00949   m_motionBuf       = new MotionInfo[_lumaAreaScaled];
00950   initStructData();
00951 }
