00953 void CodingStructure::addMiToLut(static_vector<MotionInfo, MAX_NUM_HMVP_CANDS> &lut, const MotionInfo &mi)
00954 {
00955   size_t currCnt = lut.size();
00956 
00957   bool pruned      = false;
00958   int  sameCandIdx = 0;
00959 
00960   for (int idx = 0; idx < currCnt; idx++)
00961   {
00962     if (lut[idx] == mi)
00963     {
00964       sameCandIdx = idx;
00965       pruned      = true;
00966       break;
00967     }
00968   }
00969 
00970   if (pruned || currCnt == lut.capacity())
00971   {
00972     lut.erase(lut.begin() + sameCandIdx);
00973   }
00974 
00975   lut.push_back(mi);
00976 }
