00978 void CodingStructure::resetPrevPLT(PLTBuf& prevPLT)
00979 {
00980   for (int comp = 0; comp < MAX_NUM_CHANNEL_TYPE; comp++)
00981   {
00982     prevPLT.curPLTSize[comp] = 0;
00983   }
00984 
00985   for (int comp = 0; comp < MAX_NUM_COMPONENT; comp++)
00986   {
00987     memset(prevPLT.curPLT[comp], 0, MAXPLTPREDSIZE * sizeof(Pel));
00988   }
00989 }
00990 
00991 void CodingStructure::reorderPrevPLT(PLTBuf& prevPLT, uint8_t curPLTSize[MAX_NUM_CHANNEL_TYPE], Pel curPLT[MAX_NUM_COMPONENT][MAXPLTSIZE], bool reuseflag[MAX_NUM_CHANNEL_TYPE][MAXPLTPREDSIZE], uint32_t compBegin, uint32_t numComp, bool jointPLT)
00992 {
00993   Pel stuffedPLT[MAX_NUM_COMPONENT][MAXPLTPREDSIZE];
00994   uint8_t tempCurPLTsize[MAX_NUM_CHANNEL_TYPE];
00995   uint8_t stuffPLTsize[MAX_NUM_COMPONENT];
00996 
00997   uint32_t maxPredPltSize = jointPLT ? MAXPLTPREDSIZE : MAXPLTPREDSIZE_DUALTREE;
00998 
00999   for (int i = compBegin; i < (compBegin + numComp); i++)
01000   {
01001     ComponentID comID = jointPLT ? (ComponentID)compBegin : ((i > 0) ? COMPONENT_Cb : COMPONENT_Y);
01002     tempCurPLTsize[comID] = curPLTSize[comID];
01003     stuffPLTsize[i] = 0;
01004     memcpy(stuffedPLT[i], curPLT[i], curPLTSize[comID] * sizeof(Pel));
01005   }
01006 
01007   for (int ch = compBegin; ch < (compBegin + numComp); ch++)
01008   {
01009     ComponentID comID = jointPLT ? (ComponentID)compBegin : ((ch > 0) ? COMPONENT_Cb : COMPONENT_Y);
01010     if (ch > 1) break;
01011     for (int i = 0; i < prevPLT.curPLTSize[comID]; i++)
01012     {
01013       if (tempCurPLTsize[comID] + stuffPLTsize[ch] >= maxPredPltSize)
01014       {
01015         break;
01016       }
01017 
01018       if (!reuseflag[comID][i])
01019       {
01020         if (ch == COMPONENT_Y)
01021         {
01022           stuffedPLT[0][tempCurPLTsize[comID] + stuffPLTsize[ch]] = prevPLT.curPLT[0][i];
01023         }
01024         else
01025         {
01026           stuffedPLT[1][tempCurPLTsize[comID] + stuffPLTsize[ch]] = prevPLT.curPLT[1][i];
01027           stuffedPLT[2][tempCurPLTsize[comID] + stuffPLTsize[ch]] = prevPLT.curPLT[2][i];
01028         }
01029         stuffPLTsize[ch]++;
01030       }
01031     }
01032   }
01033 
01034   for (int i = compBegin; i < (compBegin + numComp); i++)
01035   {
01036     ComponentID comID = jointPLT ? (ComponentID)compBegin : ((i > 0) ? COMPONENT_Cb : COMPONENT_Y);
01037     prevPLT.curPLTSize[comID] = curPLTSize[comID] + stuffPLTsize[comID];
01038     memcpy(prevPLT.curPLT[i], stuffedPLT[i], prevPLT.curPLTSize[comID] * sizeof(Pel));
01039     CHECK(prevPLT.curPLTSize[comID] > maxPredPltSize, " Maximum palette predictor size exceed limit");
01040   }
01041 }
01042 
01043 void CodingStructure::setPrevPLT(PLTBuf predictor)
