01048   }
01049   for (int comp = 0; comp < MAX_NUM_COMPONENT; comp++)
01050   {
01051     memcpy(prevPLT.curPLT[comp], predictor.curPLT[comp], MAXPLTPREDSIZE * sizeof(Pel));
01052   }
