01107 void CodingStructure::createCoeffs(const bool isPLTused)
01108 {
01109   const unsigned numCh = getNumberValidComponents( area.chromaFormat );
01110 
01111   for( unsigned i = 0; i < numCh; i++ )
01112   {
01113     unsigned _area = area.blocks[i].area();
01114 
01115     m_coeffs[i] = _area > 0 ? ( TCoeff* ) xMalloc( TCoeff, _area ) : nullptr;
01116     m_pcmbuf[i] = _area > 0 ? ( Pel*    ) xMalloc( Pel,    _area ) : nullptr;
01117   }
01118 
01119   if (isPLTused)
01120   {
01121     for (unsigned i = 0; i < (isChromaEnabled(area.chromaFormat) ? 2 : 1); i++)
01122     {
01123       unsigned _area = area.blocks[i].area();
01124 
01125       m_runType[i] = _area > 0 ? (bool*)xMalloc(bool, _area) : nullptr;
01126     }
01127   }
01128 }
