01130 void CodingStructure::destroyCoeffs()
01131 {
01132   for( uint32_t i = 0; i < MAX_NUM_COMPONENT; i++ )
01133   {
01134     if (m_coeffs[i])
01135     {
01136       xFree(m_coeffs[i]);
01137       m_coeffs[i] = nullptr;
01138     }
01139     if (m_pcmbuf[i])
01140     {
01141       xFree(m_pcmbuf[i]);
01142       m_pcmbuf[i] = nullptr;
01143     }
01144   }
01145 
01146   for (uint32_t i = 0; i < MAX_NUM_CHANNEL_TYPE; i++)
01147   {
01148     if (m_runType[i])
01149     {
01150       xFree(m_runType[i]);
01151       m_runType[i] = nullptr;
01152     }
01153   }
