01156 void CodingStructure::initSubStructure( CodingStructure& subStruct, const ChannelType _chType, const UnitArea &subArea, const bool &isTuEnc )
01157 {
01158   CHECK( this == &subStruct, "Trying to init self as sub-structure" );
01159 
01160   subStruct.useDbCost = false;
01161   subStruct.costDbOffset = 0;
01162 
01163   for( uint32_t i = 0; i < subStruct.area.blocks.size(); i++ )
01164   {
01165     CHECKD( subStruct.area.blocks[i].size() != subArea.blocks[i].size(), "Trying to init sub-structure of incompatible size" );
01166 
01167     subStruct.area.blocks[i].pos() = subArea.blocks[i].pos();
01168   }
01169 
01170   if( parent )
01171   {
01172     // allow this to be false at the top level (need for edge CTU's)
01173     CHECKD( !area.contains( subStruct.area ), "Trying to init sub-structure not contained in the parent" );
01174   }
01175 
01176   subStruct.parent    = this;
01177   subStruct.picture   = picture;
01178 
01179   subStruct.sps       = sps;
01180   subStruct.vps       = vps;
01181   subStruct.pps       = pps;
01182   subStruct.picHeader = picHeader;
01183   memcpy(subStruct.alfApss, alfApss, sizeof(alfApss));
01184 
01185   subStruct.lmcsAps = lmcsAps;
01186   subStruct.scalinglistAps = scalinglistAps;
01187 
01188   subStruct.slice     = slice;
01189   subStruct.baseQP    = baseQP;
01190   subStruct.prevQP[_chType]
01191                       = prevQP[_chType];
01192   subStruct.pcv       = pcv;
01193 
01194   subStruct.m_isTuEnc = isTuEnc;
01195 
01196   subStruct.motionLut = motionLut;
01197 
01198   subStruct.prevPLT = prevPLT;
01199 
01200   subStruct.treeType  = treeType;
01201   subStruct.modeType  = modeType;
01202 
01203   subStruct.initStructData( currQP[_chType] );
01204 
01205   if( isTuEnc )
01206   {
01207     CHECKD( area != subStruct.area, "Trying to init sub-structure for TU-encoding of incompatible size" );
01208 
01209     for( const auto &pcu : cus )
01210     {
01211       CodingUnit &cu = subStruct.addCU( *pcu, _chType );
01212 
01213       cu = *pcu;
01214     }
01215 
01216     for( const auto &ppu : pus )
01217     {
01218       PredictionUnit &pu = subStruct.addPU( *ppu, _chType );
01219 
01220       pu = *ppu;
01221     }
01222 
01223     unsigned numComp = vtm::getNumberValidChannels( area.chromaFormat );
01224     for( unsigned i = 0; i < numComp; i++)
01225     {
01226       ::memcpy( subStruct.m_isDecomp[i], m_isDecomp[i], (unitScale[i].scale( area.blocks[i].size() ).area() * sizeof( bool ) ) );
01227     }
01228   }
01229 }
01230 
01231 void CodingStructure::useSubStructure( const CodingStructure& subStruct, const ChannelType chType, const UnitArea &subArea, const bool cpyPred /*= true*/, const bool cpyReco /*= true*/, const bool cpyOrgResi /*= true*/, const bool cpyResi /*= true*/, const bool updateCost /*= true*/ )
01232 {
01233   UnitArea clippedArea = clipArea( subArea, *picture );
01234 
01235   setDecomp( clippedArea );
01236 
01237   CPelUnitBuf subPredBuf = cpyPred ? subStruct.getPredBuf( clippedArea ) : CPelUnitBuf();
01238   CPelUnitBuf subResiBuf = cpyResi ? subStruct.getResiBuf( clippedArea ) : CPelUnitBuf();
01239   CPelUnitBuf subRecoBuf = cpyReco ? subStruct.getRecoBuf( clippedArea ) : CPelUnitBuf();
01240 
01241   if( parent )
01242   {
01243     // copy data to picture
01244     if( cpyPred )    getPredBuf   ( clippedArea ).copyFrom( subPredBuf );
01245     if( cpyResi )    getResiBuf   ( clippedArea ).copyFrom( subResiBuf );
01246     if( cpyReco )    getRecoBuf   ( clippedArea ).copyFrom( subRecoBuf );
01247     if( cpyOrgResi ) getOrgResiBuf( clippedArea ).copyFrom( subStruct.getOrgResiBuf( clippedArea ) );
01248   }
01249 
01250   if( cpyPred ) picture->getPredBuf( clippedArea ).copyFrom( subPredBuf );
01251   if( cpyResi ) picture->getResiBuf( clippedArea ).copyFrom( subResiBuf );
01252   if( cpyReco ) picture->getRecoBuf( clippedArea ).copyFrom( subRecoBuf );
01253 
01254   if (!subStruct.m_isTuEnc && ((!slice->isIntra() || slice->getSPS()->getIBCFlag()) && chType != CHANNEL_TYPE_CHROMA))
01255   {
01256     // copy motion buffer
01257     MotionBuf ownMB  = getMotionBuf          ( clippedArea );
01258     CMotionBuf subMB = subStruct.getMotionBuf( clippedArea );
01259 
01260     ownMB.copyFrom( subMB );
01261 
01262     motionLut = subStruct.motionLut;
01263   }
01264   prevPLT = subStruct.prevPLT;
01265 
01266 
01267   if ( updateCost )
01268   {
01269     fracBits += subStruct.fracBits;
01270     dist     += subStruct.dist;
01271     cost     += subStruct.cost;
01272     costDbOffset += subStruct.costDbOffset;
01273   }
01274   if( parent )
01275   {
01276     // allow this to be false at the top level
01277     CHECKD( !area.contains( subArea ), "Trying to use a sub-structure not contained in self" );
01278   }
01279 
01280   // copy the CUs over
01281   if( subStruct.m_isTuEnc )
01282   {
01283     // don't copy if the substruct was created for encoding of the TUs
01284   }
01285   else
01286   {
01287     for( const auto &pcu : subStruct.cus )
01288     {
01289       // add an analogue CU into own CU store
01290       const UnitArea &cuPatch = *pcu;
01291       CodingUnit &cu = addCU( cuPatch, pcu->chType );
01292 
01293       // copy the CU info from subPatch
01294       cu = *pcu;
01295     }
01296   }
01297 
01298   // copy the PUs over
01299   if( subStruct.m_isTuEnc )
01300   {
01301     // don't copy if the substruct was created for encoding of the TUs
01302   }
01303   else
01304   {
01305     for( const auto &ppu : subStruct.pus )
01306     {
01307       // add an analogue PU into own PU store
01308       const UnitArea &puPatch = *ppu;
01309       PredictionUnit &pu = addPU( puPatch, ppu->chType );
01310 
01311       // copy the PU info from subPatch
01312       pu = *ppu;
01313     }
01314   }
01315   // copy the TUs over
01316   for( const auto &ptu : subStruct.tus )
01317   {
01318     // add an analogue TU into own TU store
01319     const UnitArea &tuPatch = *ptu;
01320     TransformUnit &tu = addTU( tuPatch, ptu->chType );
01321 
01322     // copy the TU info from subPatch
01323     tu = *ptu;
01324   }
01325 }
01326 
01327 void CodingStructure::copyStructure( const CodingStructure& other, const ChannelType chType, const bool copyTUs, const bool copyRecoBuf )
01328 {
01329   fracBits = other.fracBits;
01330   dist     = other.dist;
01331   cost     = other.cost;
01332   costDbOffset = other.costDbOffset;
01333   CHECKD( area != other.area, "Incompatible sizes" );
01334 
01335   const UnitArea dualITreeArea = CS::getArea( *this, this->area, chType );
01336 
01337   // copy the CUs over
01338   for (const auto &pcu : other.cus)
01339   {
01340     if( !dualITreeArea.contains( *pcu ) )
01341     {
01342       continue;
01343     }
01344     // add an analogue CU into own CU store
01345     const UnitArea &cuPatch = *pcu;
01346 
01347     CodingUnit &cu = addCU(cuPatch, pcu->chType);
01348 
01349     // copy the CU info from subPatch
01350     cu = *pcu;
01351   }
01352 
01353   // copy the PUs over
01354   for (const auto &ppu : other.pus)
01355   {
01356     if( !dualITreeArea.contains( *ppu ) )
01357     {
01358       continue;
01359     }
01360     // add an analogue PU into own PU store
01361     const UnitArea &puPatch = *ppu;
01362 
01363     PredictionUnit &pu = addPU(puPatch, ppu->chType);
01364     // copy the PU info from subPatch
01365     pu = *ppu;
01366   }
01367 
01368   if (!other.slice->isIntra() || other.slice->getSPS()->getIBCFlag())
01369   {
01370     // copy motion buffer
01371     MotionBuf  ownMB = getMotionBuf();
01372     CMotionBuf subMB = other.getMotionBuf();
01373 
01374     ownMB.copyFrom( subMB );
01375 
01376     motionLut = other.motionLut;
01377   }
01378   prevPLT = other.prevPLT;
01379 
01380   if( copyTUs )
01381   {
01382     // copy the TUs over
01383     for( const auto &ptu : other.tus )
01384     {
01385       if( !dualITreeArea.contains( *ptu ) )
01386       {
01387         continue;
01388       }
01389       // add an analogue TU into own TU store
01390       const UnitArea &tuPatch = *ptu;
01391       TransformUnit &tu = addTU( tuPatch, ptu->chType );
01392       // copy the TU info from subPatch
01393       tu = *ptu;
01394     }
01395   }
01396 
01397   if( copyRecoBuf )
01398   {
01399     CPelUnitBuf recoBuf = other.getRecoBuf( area );
01400 
01401     if( parent )
01402     {
01403       // copy data to self for neighbors
01404       getRecoBuf( area ).copyFrom( recoBuf );
01405     }
01406 
01407     // copy data to picture
01408     picture->getRecoBuf( area ).copyFrom( recoBuf );
01409     if (other.pcv->isEncoder)
01410     {
01411       CPelUnitBuf predBuf = other.getPredBuf(area);
01412       if (parent)
01413       {
01414         getPredBuf(area).copyFrom(predBuf);
01415       }
01416       picture->getPredBuf(area).copyFrom(predBuf);
01417     }
01418 
01419     // required for DebugCTU
01420     int numCh = vtm::getNumberValidChannels( area.chromaFormat );
01421     for( int i = 0; i < numCh; i++ )
01422     {
01423       const size_t _area = unitScale[i].scaleArea( area.blocks[i].area() );
01424 
01425       memcpy( m_isDecomp[i], other.m_isDecomp[i], sizeof( *m_isDecomp[0] ) * _area );
01426     }
01427   }
01428 }
01429 
01430 void CodingStructure::initStructData( const int &QP, const bool &skipMotBuf )
01431 {
01432   clearPUs();
01433   clearTUs();
01434   clearCUs();
01435 
01436   if( QP < MAX_INT )
01437   {
01438     currQP[0] = currQP[1] = QP;
01439   }
01440 
01441   if (!skipMotBuf && (!parent || ((!slice->isIntra() || slice->getSPS()->getIBCFlag()) && !m_isTuEnc)))
01442   {
01443     getMotionBuf().memset(0);
01444   }
01445 
01446   fracBits = 0;
01447   dist     = 0;
01448   cost     = MAX_DOUBLE;
01449   lumaCost = MAX_DOUBLE;
01450   costDbOffset = 0;
01451   useDbCost = false;
01452   interHad = std::numeric_limits<Distortion>::max();
01453 }
