01456 void CodingStructure::clearTUs()
01457 {
01458   int numCh = vtm::getNumberValidChannels( area.chromaFormat );
01459   for( int i = 0; i < numCh; i++ )
01460   {
01461     size_t _area = ( area.blocks[i].area() >> unitScale[i].area );
01462 
01463     memset( m_isDecomp[i], false, sizeof( *m_isDecomp[0] ) * _area );
01464     memset( m_tuIdx   [i],     0, sizeof( *m_tuIdx   [0] ) * _area );
01465   }
01466 
01467   numCh = getNumberValidComponents( area.chromaFormat );
01468   for( int i = 0; i < numCh; i++ )
01469   {
01470     m_offsets[i] = 0;
01471   }
01472 
01473   for( auto &pcu : cus )
01474   {
01475     pcu->firstTU = pcu->lastTU = nullptr;
01476   }
01477 
01478   m_tuCache.cache( tus );
01479   m_numTUs = 0;
01480 }
01481 
01482 void CodingStructure::clearPUs()
01483 {
