01487     memset( m_puIdx[i], 0, sizeof( *m_puIdx[0] ) * unitScale[i].scaleArea( area.blocks[i].area() ) );
01488   }
01489 
01490   m_puCache.cache( pus );
01491   m_numPUs = 0;
01492 
01493   for( auto &pcu : cus )
01494   {
01495     pcu->firstPU = pcu->lastPU = nullptr;
01496   }
