01511 MotionBuf CodingStructure::getMotionBuf( const Area& _area )
01512 {
01513   const CompArea& _luma = area.Y();
01514 
01515   CHECKD( !_luma.contains( _area ), "Trying to access motion information outside of this coding structure" );
01516 
01517   const Area miArea   = g_miScaling.scale( _area );
01518   const Area selfArea = g_miScaling.scale( _luma );
01519 
01520   return MotionBuf( m_motionBuf + rsAddr( miArea.pos(), selfArea.pos(), selfArea.width ), selfArea.width, miArea.size() );
01521 }
01522 
01523 const CMotionBuf CodingStructure::getMotionBuf( const Area& _area ) const
01524 {
01525   const CompArea& _luma = area.Y();
01526 
01527   CHECKD( !_luma.contains( _area ), "Trying to access motion information outside of this coding structure" );
01528 
01529   const Area miArea   = g_miScaling.scale( _area );
01530   const Area selfArea = g_miScaling.scale( _luma );
01531 
01532   return MotionBuf( m_motionBuf + rsAddr( miArea.pos(), selfArea.pos(), selfArea.width ), selfArea.width, miArea.size() );
01533 }
