01535 MotionInfo& CodingStructure::getMotionInfo( const Position& pos )
01536 {
01537   CHECKD( !area.Y().contains( pos ), "Trying to access motion information outside of this coding structure" );
01538 
01539   //return getMotionBuf().at( g_miScaling.scale( pos - area.lumaPos() ) );
01540   // bypass the motion buf calling and get the value directly
01541   const unsigned stride = g_miScaling.scaleHor( area.lumaSize().width );
01542   const Position miPos  = g_miScaling.scale( pos - area.lumaPos() );
01543 
01544   return *( m_motionBuf + miPos.y * stride + miPos.x );
01545 }
01546 
01547 const MotionInfo& CodingStructure::getMotionInfo( const Position& pos ) const
01548 {
01549   CHECKD( !area.Y().contains( pos ), "Trying to access motion information outside of this coding structure" );
01550 
01551   //return getMotionBuf().at( g_miScaling.scale( pos - area.lumaPos() ) );
