01553   const unsigned stride = g_miScaling.scaleHor( area.lumaSize().width );
01554   const Position miPos  = g_miScaling.scale( pos - area.lumaPos() );
01555 
01556   return *( m_motionBuf + miPos.y * stride + miPos.x );
