01591 PelBuf CodingStructure::getBuf( const CompArea &blk, const PictureType &type )
01592 {
01593   if (!blk.valid())
01594   {
01595     return PelBuf();
01596   }
01597 
01598   if (type == PIC_ORIGINAL)
01599   {
01600     return picture->getBuf(blk, type);
01601   }
01602 
01603   const ComponentID compID = blk.compID;
01604 
01605   PelStorage* buf = type == PIC_PREDICTION ? &m_pred : ( type == PIC_RESIDUAL ? &m_resi : ( type == PIC_RECONSTRUCTION ? &m_reco : ( type == PIC_ORG_RESI ? &m_orgr : nullptr ) ) );
01606 
01607   CHECK( !buf, "Unknown buffer requested" );
01608 
01609   CHECKD( !area.blocks[compID].contains( blk ), "Buffer not contained in self requested" );
01610 
01611   CompArea cFinal = blk;
01612   cFinal.relativeTo( area.blocks[compID] );
01613 
01614 #if !KEEP_PRED_AND_RESI_SIGNALS
01615   if( !parent && ( type == PIC_RESIDUAL || type == PIC_PREDICTION ) )
01616   {
01617     cFinal.x &= ( pcv->maxCUWidthMask  >> getComponentScaleX( blk.compID, blk.chromaFormat ) );
01618     cFinal.y &= ( pcv->maxCUHeightMask >> getComponentScaleY( blk.compID, blk.chromaFormat ) );
01619   }
01620 #endif
01621 
01622   return buf->getBuf( cFinal );
01623 }
01624 
01625 const CPelBuf CodingStructure::getBuf( const CompArea &blk, const PictureType &type ) const
01626 {
01627   if (!blk.valid())
01628   {
01629     return PelBuf();
01630   }
01631 
01632   if (type == PIC_ORIGINAL)
01633   {
01634     return picture->getBuf(blk, type);
01635   }
01636 
01637   const ComponentID compID = blk.compID;
01638 
01639   const PelStorage* buf = type == PIC_PREDICTION ? &m_pred : ( type == PIC_RESIDUAL ? &m_resi : ( type == PIC_RECONSTRUCTION ? &m_reco : ( type == PIC_ORG_RESI ? &m_orgr : nullptr ) ) );
01640 
01641   CHECK( !buf, "Unknown buffer requested" );
01642 
01643   CHECKD( !area.blocks[compID].contains( blk ), "Buffer not contained in self requested" );
01644 
01645   CompArea cFinal = blk;
01646   cFinal.relativeTo( area.blocks[compID] );
01647 
01648 #if !KEEP_PRED_AND_RESI_SIGNALS
01649   if( !parent && ( type == PIC_RESIDUAL || type == PIC_PREDICTION ) )
01650   {
01651     cFinal.x &= ( pcv->maxCUWidthMask  >> getComponentScaleX( blk.compID, blk.chromaFormat ) );
01652     cFinal.y &= ( pcv->maxCUHeightMask >> getComponentScaleY( blk.compID, blk.chromaFormat ) );
01653   }
01654 #endif
01655 
01656   return buf->getBuf( cFinal );
01657 }
