01664     return PelUnitBuf( area.chromaFormat, getBuf( unit.Y(), type ) );
01665   }
01666   else
01667   {
01668     return PelUnitBuf( area.chromaFormat, getBuf( unit.Y(), type ), getBuf( unit.Cb(), type ), getBuf( unit.Cr(), type ) );
