01685 const CodingUnit* CodingStructure::getCURestricted( const Position &pos, const CodingUnit& curCu, const ChannelType _chType ) const
01686 {
01687   const CodingUnit* cu = getCU( pos, _chType );
01688   // exists       same slice and tile                  cu precedes curCu in encoding order
01689   //                                                  (thus, is either from parent CS in RD-search or its index is lower)
01690   const bool wavefrontsEnabled = curCu.slice->getSPS()->getEntropyCodingSyncEnabledFlag();
01691   int ctuSizeBit = floorLog2(curCu.cs->sps->getMaxCUWidth());
01692   int xNbY  = pos.x << getChannelTypeScaleX( _chType, curCu.chromaFormat );
01693   int xCurr = curCu.blocks[_chType].x << getChannelTypeScaleX( _chType, curCu.chromaFormat );
01694   bool addCheck = (wavefrontsEnabled && (xNbY >> ctuSizeBit) >= (xCurr >> ctuSizeBit) + 1 ) ? false : true;
01695   if( cu && CU::isSameSliceAndTile( *cu, curCu ) && ( cu->cs != curCu.cs || cu->idx <= curCu.idx ) && addCheck)
01696   {
01697     return cu;
01698   }
01699   else
01700   {
01701     return nullptr;
01702   }
01703 }
01704 
01705 const CodingUnit* CodingStructure::getCURestricted( const Position &pos, const Position curPos, const unsigned curSliceIdx, const unsigned curTileIdx, const ChannelType _chType ) const
01706 {
01707   const CodingUnit* cu = getCU( pos, _chType );
01708   const bool wavefrontsEnabled = this->slice->getSPS()->getEntropyCodingSyncEnabledFlag();
01709   int ctuSizeBit = floorLog2(this->sps->getMaxCUWidth());
01710   int xNbY  = pos.x << getChannelTypeScaleX( _chType, this->area.chromaFormat );
01711   int xCurr = curPos.x << getChannelTypeScaleX( _chType, this->area.chromaFormat );
01712   bool addCheck = (wavefrontsEnabled && (xNbY >> ctuSizeBit) >= (xCurr >> ctuSizeBit) + 1 ) ? false : true;
01713   return ( cu && cu->slice->getIndependentSliceIdx() == curSliceIdx && cu->tileIdx == curTileIdx && addCheck ) ? cu : nullptr;
01714 }
