01716 const PredictionUnit* CodingStructure::getPURestricted( const Position &pos, const PredictionUnit& curPu, const ChannelType _chType ) const
01717 {
01718   const PredictionUnit* pu = getPU( pos, _chType );
01719   // exists       same slice and tile                  pu precedes curPu in encoding order
01720   //                                                  (thus, is either from parent CS in RD-search or its index is lower)
01721   const bool wavefrontsEnabled = curPu.cu->slice->getSPS()->getEntropyCodingSyncEnabledFlag();
01722   int ctuSizeBit = floorLog2(curPu.cs->sps->getMaxCUWidth());
01723   int xNbY  = pos.x << getChannelTypeScaleX( _chType, curPu.chromaFormat );
01724   int xCurr = curPu.blocks[_chType].x << getChannelTypeScaleX( _chType, curPu.chromaFormat );
01725   bool addCheck = (wavefrontsEnabled && (xNbY >> ctuSizeBit) >= (xCurr >> ctuSizeBit) + 1 ) ? false : true;
01726   if( pu && CU::isSameSliceAndTile( *pu->cu, *curPu.cu ) && ( pu->cs != curPu.cs || pu->idx <= curPu.idx ) && addCheck )
01727   {
01728     return pu;
01729   }
01730   else
01731   {
01732     return nullptr;
01733   }
